    def orbit(r, c):
        seen = {(r, c)}
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            candidates = [(j, i)]
            # The repeated design is reflected about index 15.5 (i+j=31).
            if 0 <= 31 - i < h:
                candidates.append((31 - i, j))
            if 0 <= 31 - j < w:
